(() => {
  'use strict';

  const API_BASE_URL = 'http://localhost:5001';
  const STORAGE_USER_KEY = 'user';
  const STORAGE_TOKEN_KEY = 'token';

  const OPEN_HOUR = 9;
  const CLOSE_HOUR = 16;
  const MIN_BOOKING_MINUTES = 60;
  const MAX_BOOKING_MINUTES = 120;

  const elements = {
    profileButton: document.getElementById('profileButton'),
    profilePopup: document.getElementById('profilePopup'),
    logoutButton: document.getElementById('logoutButton'),
    floorFilter: document.getElementById('floorFilter'),
    bookingDateFilter: document.getElementById('bookingDateFilter'),
    thaiDateLabel: document.getElementById('thaiDateLabel'),
    roomSearch: document.getElementById('roomSearch'),
    clearFiltersButton: document.getElementById('clearFiltersButton'),
    roomCount: document.getElementById('roomCount'),
    statusMessage: document.getElementById('statusMessage'),
    roomList: document.getElementById('roomList'),
    bookingModal: document.getElementById('bookingModal'),
    closeBookingModal: document.getElementById('closeBookingModal'),
    cancelBookingButton: document.getElementById('cancelBookingButton'),
    bookingForm: document.getElementById('bookingForm'),
    bookingDate: document.getElementById('bookingDate'),
    startTime: document.getElementById('startTime'),
    endTime: document.getElementById('endTime'),
    bookingPurpose: document.getElementById('bookingPurpose'),
    selectedRoomName: document.getElementById('selectedRoomName'),
    bookingError: document.getElementById('bookingError'),
    submitBookingButton: document.getElementById('submitBookingButton')
  };

  let currentUser = readStoredUser();
  let rooms = [];
  let selectedRoom = null;

  function readStoredUser() {
    try {
      const value = localStorage.getItem(STORAGE_USER_KEY);
      return value ? JSON.parse(value) : null;
    } catch (error) {
      console.error('Unable to read stored user:', error);
      return null;
    }
  }

  function getToken() {
    return localStorage.getItem(STORAGE_TOKEN_KEY) || '';
  }

  function getUserValue(...keys) {
    for (const key of keys) {
      if (
        currentUser &&
        currentUser[key] !== undefined &&
        currentUser[key] !== null &&
        currentUser[key] !== ''
      ) {
        return String(currentUser[key]);
      }
    }

    return '-';
  }

  function setText(id, value) {
    const node = document.getElementById(id);

    if (node) {
      node.textContent = value || '-';
    }
  }

  function populateProfile() {
    setText(
      'profileName',
      getUserValue('name', 'full_name', 'fullname', 'display_name')
    );

    setText(
      'profileUsername',
      getUserValue('username', 'user_name', 'student_id')
    );

    setText(
      'profileFaculty',
      getUserValue('faculty', 'faculty_name')
    );

    setText(
      'profileDepartment',
      getUserValue('department', 'major', 'department_name')
    );

    setText('profileEmail', getUserValue('email'));
  }

  function localISODate(date = new Date()) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');

    return `${year}-${month}-${day}`;
  }

  function formatThaiDate(dateString) {
    if (!dateString) {
      return 'เลือกวันที่ต้องการจอง';
    }

    const date = new Date(`${dateString}T00:00:00`);

    if (Number.isNaN(date.getTime())) {
      return 'เลือกวันที่ต้องการจอง';
    }

    return new Intl.DateTimeFormat('th-TH', {
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    }).format(date);
  }

  function setStatus(message, type = 'info') {
    elements.statusMessage.textContent = message;
    elements.statusMessage.className = `status-message status-${type}`;
    elements.statusMessage.hidden = !message;
  }

  function getRoomName(room) {
    return room.room_name ?? room.name ?? room.roomName ?? 'ไม่ระบุชื่อห้อง';
  }

  function getRoomFloor(room) {
    const raw =
      room.floor ??
      room.floor_number ??
      room.floorNumber ??
      room.building_floor;

    if (raw === undefined || raw === null || raw === '') {
      const match = String(getRoomName(room)).match(/(?:^|\D)([123])(?:\D|$)/);
      return match ? match[1] : '';
    }

    const match = String(raw).match(/[123]/);
    return match ? match[0] : String(raw);
  }

  function getRoomCapacity(room) {
    const value =
      room.capacity ??
      room.room_capacity ??
      room.people_capacity;

    return value === undefined || value === null || value === ''
      ? 'ไม่ระบุ'
      : value;
  }

  function getRoomDescription(room) {
    return (
      room.description ??
      room.facilities ??
      room.equipment ??
      room.detail ??
      'ไม่มีรายละเอียดเพิ่มเติม'
    );
  }

  function escapeHTML(value) {
    return String(value ?? '').replace(/[&<>"']/g, character => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;'
    })[character]);
  }

  function getFilteredRooms() {
    const floor = elements.floorFilter.value;
    const search = elements.roomSearch.value.trim().toLocaleLowerCase('th-TH');

    return rooms.filter(room => {
      const floorMatches =
        floor === 'all' || getRoomFloor(room) === floor;

      const nameMatches = getRoomName(room)
        .toLocaleLowerCase('th-TH')
        .includes(search);

      return floorMatches && nameMatches;
    });
  }

  function renderRooms() {
    const filteredRooms = getFilteredRooms();

    elements.roomList.replaceChildren();
    elements.roomCount.textContent = `พบ ${filteredRooms.length} ห้อง`;

    if (!filteredRooms.length) {
      setStatus(
        rooms.length
          ? 'ไม่พบห้องที่ตรงกับเงื่อนไขการค้นหา'
          : 'ไม่พบข้อมูลห้อง',
        'empty'
      );
      return;
    }

    setStatus('เลือกวันที่และตรวจสอบรายละเอียดก่อนทำการจอง', 'info');

    const grouped = new Map();

    filteredRooms.forEach(room => {
      const floor = getRoomFloor(room) || 'อื่น ๆ';

      if (!grouped.has(floor)) {
        grouped.set(floor, []);
      }

      grouped.get(floor).push(room);
    });

    const sortedFloors = [...grouped.keys()].sort((a, b) => {
      if (a === 'อื่น ๆ') return 1;
      if (b === 'อื่น ๆ') return -1;
      return Number(a) - Number(b);
    });

    sortedFloors.forEach(floor => {
      const section = document.createElement('section');
      section.className = 'floor-section';

      const heading = document.createElement('div');
      heading.className = 'floor-heading';

      const floorNumber = document.createElement('span');
      floorNumber.className = 'floor-number';
      floorNumber.textContent = floor === 'อื่น ๆ' ? '•' : floor;

      const title = document.createElement('h3');
      title.textContent = floor === 'อื่น ๆ' ? 'ห้องอื่น ๆ' : `ชั้น ${floor}`;

      heading.append(floorNumber, title);

      const grid = document.createElement('div');
      grid.className = 'room-grid';

      grouped.get(floor).forEach(room => {
        const card = document.createElement('article');
        card.className = 'room-card';

        const roomName = getRoomName(room);
        const capacity = getRoomCapacity(room);
        const description = getRoomDescription(room);

        card.innerHTML = `
          <div class="room-card-top">
            <span class="room-floor-tag">
              ${floor === 'อื่น ๆ' ? 'ไม่ระบุชั้น' : `ชั้น ${escapeHTML(floor)}`}
            </span>
            <span class="room-status">
              <span class="availability-dot"></span>
              ตรวจสอบก่อนจอง
            </span>
          </div>
          <h4 class="room-name">${escapeHTML(roomName)}</h4>
          <p class="room-capacity">
            <span aria-hidden="true">♧</span>
            รองรับ ${escapeHTML(capacity)} คน
          </p>
          <p class="room-description">${escapeHTML(description)}</p>
          <div class="room-hours">
            <span>เวลาให้บริการ</span>
            <strong>09:00–16:00 น.</strong>
          </div>
          <button type="button" class="button button-primary button-full book-room-button">
            จองห้องนี้ <span aria-hidden="true">→</span>
          </button>
        `;

        card
          .querySelector('.book-room-button')
          .addEventListener('click', () => openBookingModal(room));

        grid.appendChild(card);
      });

      section.append(heading, grid);
      elements.roomList.appendChild(section);
    });
  }

  async function loadRooms() {
    setStatus('กำลังโหลดข้อมูลห้อง...', 'info');
    elements.roomCount.textContent = 'กำลังโหลดข้อมูลห้อง...';

    try {
      const headers = {};

      if (getToken()) {
        headers.Authorization = `Bearer ${getToken()}`;
      }

      const response = await fetch(`${API_BASE_URL}/api/rooms`, {
        headers
      });

      if (!response.ok) {
        throw new Error(`โหลดข้อมูลห้องไม่สำเร็จ (${response.status})`);
      }

      const data = await response.json();

      rooms = Array.isArray(data)
        ? data
        : Array.isArray(data.rooms)
          ? data.rooms
          : [];

      renderRooms();
    } catch (error) {
      console.error('Load rooms error:', error);

      rooms = [];
      elements.roomList.replaceChildren();
      elements.roomCount.textContent = 'โหลดข้อมูลไม่สำเร็จ';

      setStatus(
        'ไม่สามารถโหลดข้อมูลห้องได้ กรุณาตรวจสอบว่า Backend เปิดอยู่ที่ http://localhost:5001 และ API /api/rooms ใช้งานได้',
        'error'
      );
    }
  }

  function makeTimeOptions() {
    const options = [];

    for (
      let minutes = OPEN_HOUR * 60;
      minutes <= CLOSE_HOUR * 60;
      minutes += 30
    ) {
      const hours = Math.floor(minutes / 60);
      const mins = minutes % 60;

      const value =
        `${String(hours).padStart(2, '0')}:` +
        `${String(mins).padStart(2, '0')}`;

      options.push({ value, label: value });
    }

    return options;
  }

  function minutesFromTime(value) {
    const [hours, minutes] = value.split(':').map(Number);
    return hours * 60 + minutes;
  }

  function fillStartTimes(selected = '09:00') {
    const options = makeTimeOptions().filter(
      option => minutesFromTime(option.value) < CLOSE_HOUR * 60
    );

    elements.startTime.innerHTML = options
      .map(option =>
        `<option value="${option.value}">${option.label} น.</option>`
      )
      .join('');

    elements.startTime.value = selected;
    fillEndTimes();
  }

  function fillEndTimes(selected) {
    const start = minutesFromTime(elements.startTime.value || '09:00');

    const options = makeTimeOptions().filter(option => {
      const end = minutesFromTime(option.value);
      const duration = end - start;

      return (
        duration >= MIN_BOOKING_MINUTES &&
        duration <= MAX_BOOKING_MINUTES
      );
    });

    const previous = selected || elements.endTime.value;

    elements.endTime.innerHTML = options
      .map(option =>
        `<option value="${option.value}">${option.label} น.</option>`
      )
      .join('');

    if (options.some(option => option.value === previous)) {
      elements.endTime.value = previous;
    } else if (options.length) {
      elements.endTime.value = options[0].value;
    }
  }

  function openBookingModal(room) {
    selectedRoom = room;
    elements.selectedRoomName.textContent = getRoomName(room);

    const date = elements.bookingDateFilter.value || localISODate();

    elements.bookingDate.min = localISODate();
    elements.bookingDate.value = date;
    elements.bookingPurpose.value = '';
    elements.bookingError.hidden = true;

    fillStartTimes('09:00');

    elements.bookingModal.hidden = false;
    document.body.classList.add('modal-open');
    elements.closeBookingModal.focus();
  }

  function closeBookingModal() {
    elements.bookingModal.hidden = true;
    document.body.classList.remove('modal-open');
    selectedRoom = null;
  }

  function showBookingError(message) {
    elements.bookingError.textContent = message;
    elements.bookingError.hidden = false;
  }

  function validateBooking(dateString, startTime, endTime) {
    if (!dateString) {
      return 'กรุณาเลือกวันที่จอง';
    }

    if (dateString < localISODate()) {
      return 'ไม่สามารถจองวันที่ผ่านมาแล้วได้';
    }

    const date = new Date(`${dateString}T00:00:00`);
    const day = date.getDay();

    if (day === 0 || day === 6) {
      return 'ระบบเปิดให้จองเฉพาะวันจันทร์–ศุกร์';
    }

    const start = minutesFromTime(startTime);
    const end = minutesFromTime(endTime);

    if (start < OPEN_HOUR * 60 || end > CLOSE_HOUR * 60) {
      return 'เวลาจองต้องอยู่ระหว่าง 09:00–16:00 น.';
    }

    if (end - start < MIN_BOOKING_MINUTES) {
      return 'ต้องจองอย่างน้อย 1 ชั่วโมง';
    }

    if (end - start > MAX_BOOKING_MINUTES) {
      return 'จองได้ไม่เกิน 2 ชั่วโมงต่อครั้ง';
    }

    return '';
  }

  async function submitBooking(event) {
    event.preventDefault();

    if (!selectedRoom) return;

    const userId =
      currentUser?.user_id ??
      currentUser?.id ??
      currentUser?.userId;

    if (userId === undefined || userId === null || userId === '') {
      showBookingError('ไม่พบรหัสผู้ใช้ กรุณาเข้าสู่ระบบใหม่อีกครั้ง');
      return;
    }

    const date = elements.bookingDate.value;
    const startTime = elements.startTime.value;
    const endTime = elements.endTime.value;

    const validationError = validateBooking(date, startTime, endTime);

    if (validationError) {
      showBookingError(validationError);
      return;
    }

    const payload = {
      user_id: userId,
      room: getRoomName(selectedRoom),
      date,
      start_time: startTime,
      end_time: endTime,
      purpose: elements.bookingPurpose.value.trim()
    };

    elements.submitBookingButton.disabled = true;
    elements.submitBookingButton.textContent = 'กำลังบันทึก...';
    elements.bookingError.hidden = true;

    try {
      const headers = {
        'Content-Type': 'application/json'
      };

      if (getToken()) {
        headers.Authorization = `Bearer ${getToken()}`;
      }

      const response = await fetch(`${API_BASE_URL}/api/bookings`, {
        method: 'POST',
        headers,
        body: JSON.stringify(payload)
      });

      const result = await response.json().catch(() => ({}));

      if (!response.ok) {
        throw new Error(
          result.message ||
          result.error ||
          'จองห้องไม่สำเร็จ กรุณาตรวจสอบวันและเวลาที่เลือก'
        );
      }

      closeBookingModal();
      window.alert(result.message || 'ส่งคำขอจองห้องเรียบร้อยแล้ว');
    } catch (error) {
      console.error('Booking error:', error);

      showBookingError(
        error.message || 'เกิดข้อผิดพลาดในการจอง กรุณาลองใหม่'
      );
    } finally {
      elements.submitBookingButton.disabled = false;
      elements.submitBookingButton.textContent = 'ยืนยันการจอง';
    }
  }

  function toggleProfile() {
    const isOpening = elements.profilePopup.hidden;

    elements.profilePopup.hidden = !isOpening;
    elements.profileButton.setAttribute(
      'aria-expanded',
      String(isOpening)
    );
  }

  function logout() {
    localStorage.removeItem(STORAGE_TOKEN_KEY);
    localStorage.removeItem(STORAGE_USER_KEY);
    window.location.href = '/';
  }

  function clearFilters() {
    elements.floorFilter.value = 'all';
    elements.bookingDateFilter.value = '';
    elements.thaiDateLabel.textContent = 'เลือกวันที่ต้องการจอง';
    elements.roomSearch.value = '';

    renderRooms();
  }

  function bindEvents() {
    elements.profileButton.addEventListener('click', toggleProfile);
    elements.logoutButton.addEventListener('click', logout);

    elements.floorFilter.addEventListener('change', renderRooms);
    elements.roomSearch.addEventListener('input', renderRooms);

    elements.bookingDateFilter.addEventListener('change', () => {
      elements.thaiDateLabel.textContent =
        formatThaiDate(elements.bookingDateFilter.value);
    });

    elements.clearFiltersButton.addEventListener('click', clearFilters);

    elements.closeBookingModal.addEventListener(
      'click',
      closeBookingModal
    );

    elements.cancelBookingButton.addEventListener(
      'click',
      closeBookingModal
    );

    elements.bookingModal.addEventListener('click', event => {
      if (event.target === elements.bookingModal) {
        closeBookingModal();
      }
    });

    elements.bookingForm.addEventListener('submit', submitBooking);

    elements.startTime.addEventListener('change', () => {
      fillEndTimes();
    });

    document.addEventListener('click', event => {
      if (
        !elements.profilePopup.hidden &&
        !elements.profilePopup.contains(event.target) &&
        !elements.profileButton.contains(event.target)
      ) {
        elements.profilePopup.hidden = true;
        elements.profileButton.setAttribute('aria-expanded', 'false');
      }
    });

    document.addEventListener('keydown', event => {
      if (event.key === 'Escape') {
        if (!elements.bookingModal.hidden) {
          closeBookingModal();
        }

        elements.profilePopup.hidden = true;
        elements.profileButton.setAttribute('aria-expanded', 'false');
      }
    });
  }

  function init() {
    if (!currentUser) {
      window.location.href = '/';
      return;
    }

    populateProfile();

    elements.bookingDateFilter.min = localISODate();
    elements.bookingDate.min = localISODate();

    bindEvents();
    loadRooms();
  }

  init();
})();
